```java
import java.util.*;

public class Retention {
    record Request(String id, byte[] body) {}

    static final Map<String, Request> LEAKY = new HashMap<>();   // static root: lives forever.

    static final int LIMIT = 3;
    static final Map<String, Request> BOUNDED = new LinkedHashMap<>(16, 0.75f, true) {
        @Override protected boolean removeEldestEntry(Map.Entry<String, Request> e) {
            return size() > LIMIT;                                // evict: removes the path.
        }
    };

    public static void main(String[] args) {
        for (int i = 0; i < 10; i++) {
            Request r = new Request("r" + i, new byte[1024]);
            LEAKY.put(r.id(), r);
            BOUNDED.put(r.id(), r);
        }
        System.out.println(LEAKY.size() + " " + BOUNDED.size());   // 10 3
        System.out.println(BOUNDED.keySet());                      // [r7, r8, r9]
    }
}
```

In a real service the loop never stops, so LEAKY grows without limit while BOUNDED stays at 3.

